/* ==========================================
   【长夜＆机械之心】列表面板 - 字体清晰版
   『作者：长夜何其多』禁二传商用
   ========================================== */

/* 1. 底层背景：粉红星空图源 */
.chat-app, .chat-inbox, .chat-scroll {
  background-color: #fcf1f5 !important;
  background-image: url('https://picui.ogmua.cn/s1/2026/11/08/6aefd141b1ab1.webp') !important;
  background-size: cover !important; 
  background-position: center !important; 
  background-repeat: no-repeat !important; 
  background-attachment: fixed !important; 
}

/* 2. 顶栏：“消息”位置微调 */
.chat-head-inbox { background: transparent !important; box-shadow: none !important; }
.chat-inbox-title, [class*="inbox-title"], .chat-head-inbox h1, .chat-head-inbox h2, .chat-head-inbox [class*="title"] {
  color: #4a3340 !important;
  font-family: 'Cinzel', 'Songti SC', serif !important;
  font-weight: 700 !important;
  font-size: 25px !important; 
  text-shadow: 0 2px 4px rgba(255,255,255,0.8) !important; 
  display: inline-block !important; 
  transform: translate(25px, -5px) !important; 
}

/* 切换器 */
.chat-inbox-filter button {
  background: rgba(255, 255, 255, 0.6) !important;
  color: #8a7380 !important;
  border-radius: 20px !important;
  border: 1px solid rgba(255, 255, 255, 0.9) !important;
}
.chat-inbox-filter button.on {
  background: rgba(255, 255, 255, 1) !important;
  color: #4a3340 !important;
  box-shadow: 0 4px 12px rgba(220,150,185,0.3) !important;
  border: 1px solid #ffffff !important;
}

/* ==========================================
   核心：圆角面板（保留你的通透感）
   ========================================== */
.chat-list-sheet {
  background-color: #fff5f8 !important; 
  background-image: none !important; 

  border-radius: 24px !important; 
  margin: 20px 16px !important; 
  overflow: visible !important; 

  border: 1.5px solid #ffffff !important;
  box-shadow: 0 12px 32px -8px rgba(120, 70, 100, 0.2), inset 0 2px 8px rgba(255, 255, 255, 1) !important; 
  position: relative !important;
}

/* 清除内部底色，保留透出星空的感觉 */
.chat-list-sheet *, 
.chat-list-sheet .chat-scroll,
.chat-row-wrap, 
.chat-row,
[class*="row-wrap"], 
[class*="chat-list"] {
  background-color: transparent !important;
  background-image: none !important;
}

/* 【面板顶部的心电图】 */
.chat-list-sheet::before {
  content: "" !important;
  position: absolute !important;
  top: -8px !important; left: 0 !important; right: 0 !important; height: 12px !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 20" preserveAspectRatio="none"><path d="M0 15 L10 15 L15 15 L18 5 L22 18 L25 10 L28 15 L40 15 L43 12 L46 15 L60 15 L63 5 L67 18 L70 10 L73 15 L85 15 L88 12 L91 15 L100 15" fill="none" stroke="%23ec7ca0" stroke-width="1.5" opacity="0.8"/></svg>') !important;
  background-size: 120px 12px !important; 
  background-repeat: repeat-x !important;
  animation: row-ecg 3s linear infinite !important;
  z-index: 99 !important;
}

/* 【面板底部的心电图】 */
.chat-list-sheet::after {
  content: "" !important;
  position: absolute !important;
  bottom: -8px !important; left: 0 !important; right: 0 !important; height: 12px !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 20" preserveAspectRatio="none"><path d="M0 15 L10 15 L15 15 L18 5 L22 18 L25 10 L28 15 L40 15 L43 12 L46 15 L60 15 L63 5 L67 18 L70 10 L73 15 L85 15 L88 12 L91 15 L100 15" fill="none" stroke="%23ec7ca0" stroke-width="1.5" opacity="0.8"/></svg>') !important;
  background-size: 120px 12px !important; 
  background-repeat: repeat-x !important;
  animation: row-ecg-reverse 3s linear infinite !important;
  z-index: 99 !important;
}

@keyframes row-ecg { 0% { background-position: 0 0; } 100% { background-position: -120px 0; } }
@keyframes row-ecg-reverse { 0% { background-position: 0 0; } 100% { background-position: 120px 0; } }

/* ==========================================
   内部：分割线与文字
   ========================================== */
.chat-row-wrap {
  border-bottom: 1px solid rgba(236, 124, 160, 0.3) !important; 
}
.chat-row-wrap:last-child {
  border-bottom: none !important;
}
.chat-row {
  padding: 14px 16px !important; 
}

/* 头像果冻效果 */
.chat-ava-list {
  border-radius: 14px !important;
  border: 1px solid rgba(255, 240, 246, 1) !important;
  background: linear-gradient(140deg, #ffeef5 0%, #fdd9e6 45%, #fbcbdf 100%) !important;
  box-shadow: inset 0 1.5px 0 rgba(255,255,255,1), 0 0 0 2px rgba(255,255,255,0.9), 0 4px 12px -2px rgba(220,150,185,0.2) !important;
  padding: 2px !important;
}
.chat-ava-list img { border-radius: 11px !important; }

/* 👇【修改】人物名字：字号精准调整到 14.8px */
.chat-row strong,
.chat-row-top strong,
.chat-row [class*="name"],
.chat-row [class*="title"] {
  color: #111111 !important; 
  text-shadow: none !important; 
  font-family: 'Cinzel', 'Songti SC', serif !important;
  font-weight: 400 !important; 
  font-size: 14.8px !important; /* 听你的，14.8px */
}

/* 聊天预览文字 */
.chat-row-preview,
.chat-row [class*="preview"] {
  color: #444444 !important; 
  text-shadow: none !important;
  font-family: 'Songti SC', 'STSong', serif !important;
  font-size: 12px !important;
  font-weight: 400 !important;
  margin-top: 2px !important;
}

/* 时间 */
.chat-row-meta,
.chat-row [class*="time"],
.chat-row [class*="meta"] { 
  color: #666666 !important; 
  text-shadow: none !important;
  font-size: 11px !important; 
  font-weight: 400 !important;
}

.chat-row-unread {
  background: linear-gradient(135deg, #ff8da1 0%, #ec7ca0 100%) !important;
  color: #ffffff !important;
  border-radius: 50% !important;
  box-shadow: inset 0 1px 1px rgba(255,255,255,0.8), 0 2px 8px rgba(236,124,160,0.5) !important;
}
.chat-row-pin-mark {
  background: #ffffff !important;
  color: #c98daa !important;
  border: 1px solid rgba(236, 124, 160, 0.3) !important;
  border-radius: 6px !important;
}

/* 底栏 Tab */
.chat-tabdock { background: transparent !important; }
.chat-tabdock-pill {
  background: #ffffff !important; 
  border: 1.5px solid rgba(255, 255, 255, 1) !important;
  box-shadow: 0 8px 24px rgba(220,150,185,0.2) !important;
  border-radius: 28px !important;
}
.chat-tabdock-pill * { color: #8a7380 !important; }
.chat-tabdock-pill .on * { color: #ec7ca0 !important; }
